import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import axios from 'axios';

const API = 'http://localhost:5000/api';

function NewspaperDetail({ mode }) {
  const { id } = useParams();
  const { user, showToast } = useAuth();
  const navigate = useNavigate();
  const [newspaper, setNewspaper] = useState(null);
  const [sections, setSections] = useState([]);
  const [reporters, setReporters] = useState([]);
  const [pendingConfirms, setPendingConfirms] = useState(0);
  const [loading, setLoading] = useState(true);

  const isAdmin = mode === 'admin';

  useEffect(() => {
    if (!user || (isAdmin && user.role !== 'admin') || (!isAdmin && !['admin', 'reporter'].includes(user.role))) {
      navigate('/');
      return;
    }
    fetchDetail();
    if (isAdmin) fetchReporters();
  }, [user, id]);

  const fetchDetail = async () => {
    try {
      const token = localStorage.getItem('dju_token');
      const res = await axios.get(`${API}/newspapers/${id}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setNewspaper(res.data.newspaper);
      setSections(res.data.sections);
      setPendingConfirms(res.data.pending_confirms);
    } catch (err) {
      showToast('신문 정보를 불러올 수 없습니다.', 'error');
    } finally {
      setLoading(false);
    }
  };

  const fetchReporters = async () => {
    try {
      const token = localStorage.getItem('dju_token');
      const res = await axios.get(`${API}/newspapers/reporters/list`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setReporters(res.data.reporters);
    } catch (err) { /* ignore */ }
  };

  const handleAssignReporter = async (sectionId, reporterId) => {
    try {
      const token = localStorage.getItem('dju_token');
      await axios.put(`${API}/newspapers/sections/${sectionId}/assign`,
        { reporter_id: reporterId || null },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      showToast('담당 기자가 변경되었습니다.', 'success');
      fetchDetail();
    } catch (err) {
      showToast('기자 지정에 실패했습니다.', 'error');
    }
  };

  const handleClickSection = (section) => {
    // 기자인 경우 본인 담당 지면만 클릭 가능
    if (user.role === 'reporter' && section.assigned_reporter_id !== user.id) {
      return;
    }
    navigate(`/write/article/${section.id}`);
  };

  const getStatusBadge = (status) => {
    switch(status) {
      case 'submitted':
        return <span className="bg-orange-100 text-orange-700 text-xs font-bold px-2 py-1 rounded-full">컨펌 요청</span>;
      case 'confirmed':
        return <span className="bg-green-100 text-green-700 text-xs font-bold px-2 py-1 rounded-full">컨펌 완료</span>;
      case 'rejected':
        return <span className="bg-red-100 text-red-700 text-xs font-bold px-2 py-1 rounded-full">반려</span>;
      case 'draft':
        return <span className="bg-blue-100 text-blue-700 text-xs font-bold px-2 py-1 rounded-full">작성 중</span>;
      default:
        return <span className="bg-gray-100 text-gray-500 text-xs font-bold px-2 py-1 rounded-full">미작성</span>;
    }
  };

  if (loading) {
    return (
      <main className="max-w-6xl mx-auto px-6 py-20 text-center text-gray-400">
        <i className="fas fa-spinner fa-spin text-3xl mb-4"></i>
        <p>불러오는 중...</p>
      </main>
    );
  }

  if (!newspaper) return null;

  // 면별 그룹핑
  const pageGroups = {};
  sections.forEach(sec => {
    const p = sec.page_number;
    if (!pageGroups[p]) pageGroups[p] = [];
    pageGroups[p].push(sec);
  });

  return (
    <main className="max-w-6xl mx-auto px-6 py-8">
      {/* 뒤로가기 */}
      <button
        onClick={() => navigate(isAdmin ? '/admin' : '/write')}
        className="text-gray-400 hover:text-[#004b93] mb-6 flex items-center space-x-2 transition"
      >
        <i className="fas fa-arrow-left"></i>
        <span className="font-semibold">{isAdmin ? '관리자 패널' : '기사 작성'}으로 돌아가기</span>
      </button>

      {/* 제목 영역 */}
      <div className="flex items-center justify-between mb-8">
        <div>
          <h1 className="text-2xl font-extrabold text-gray-900">
            {newspaper.title} {isAdmin ? '지면 운용 현황' : '지면 현황'}
          </h1>
          <p className="text-gray-500 mt-1">
            발행일: {new Date(newspaper.publish_date).toLocaleDateString('ko-KR')}
            {pendingConfirms > 0 && isAdmin && (
              <span className="ml-3 bg-red-500 text-white text-xs font-bold px-2 py-1 rounded-full">
                컨펌 대기 {pendingConfirms}건
              </span>
            )}
          </p>
        </div>
      </div>

      {/* 지면 목록 */}
      {Object.keys(pageGroups).sort((a,b) => a - b).map(page => (
        <div key={page} className="mb-8">
          <h2 className="text-lg font-extrabold text-[#004b93] mb-4 pb-2 border-b border-gray-200">
            {page}면
          </h2>
          <div className="space-y-3">
            {pageGroups[page].map(sec => {
              const isMySection = user.role === 'admin' || sec.assigned_reporter_id === user.id;
              const articleNotReady = !sec.article_status || sec.article_status === 'empty' || sec.article_status === 'draft';
              const hasConfirmRequest = sec.article_status === 'submitted';

              return (
                <div
                  key={sec.id}
                  onClick={() => {
                    if (isAdmin) {
                      // 편집장: 컨펌 요청된 기사만 컨펌 페이지 진입 가능, 하지만 모든 기사 수정/접근 가능
                      navigate(`/write/article/${sec.id}`);
                    } else {
                      handleClickSection(sec);
                    }
                  }}
                  className={`p-5 rounded-2xl border transition ${
                    isMySection
                      ? 'bg-white border-gray-100 hover:shadow-lg hover:border-[#004b93]/20 cursor-pointer'
                      : 'bg-gray-50 border-gray-100 opacity-60 cursor-default'
                  } ${isMySection && !isAdmin ? 'ring-2 ring-[#004b93]/20' : ''}`}
                >
                  <div className="flex items-center justify-between">
                    <div className="flex items-center space-x-4 flex-1">
                      {/* 지면 이름 */}
                      <div className="w-32">
                        <span className="font-extrabold text-gray-900">{sec.section_name}</span>
                      </div>

                      {/* 기사 제목 또는 미작성 */}
                      <div className="flex-1">
                        {sec.article_title ? (
                          <span className="text-sm text-gray-700 font-semibold">{sec.article_title}</span>
                        ) : (
                          <span className="text-sm text-gray-400 italic">
                            {sec.article_status === 'draft' ? '작성 중입니다...' : '작성이 완료되지 않았습니다.'}
                          </span>
                        )}
                      </div>

                      {/* 분량 정보 (관리자만) */}
                      {isAdmin && (
                        <div className="hidden lg:flex items-center space-x-3 text-xs text-gray-400">
                          {sec.volume && <span>분량 {sec.volume}</span>}
                          {sec.title_max_length && <span>제목 {sec.title_max_length}자</span>}
                          {sec.subtitle_max_length && <span>부제 {sec.subtitle_max_length}자</span>}
                          <span>사진 {sec.photo_count}장{sec.photo_required ? '(필수)' : ''}</span>
                          {sec.caption_required ? <span>캡션필수</span> : null}
                        </div>
                      )}
                    </div>

                    <div className="flex items-center space-x-3">
                      {/* 담당 기자 */}
                      {isAdmin ? (
                        <select
                          value={sec.assigned_reporter_id || ''}
                          onChange={(e) => {
                            e.stopPropagation();
                            handleAssignReporter(sec.id, parseInt(e.target.value) || null);
                          }}
                          onClick={(e) => e.stopPropagation()}
                          className="px-2 py-1 rounded-lg border border-gray-200 text-xs"
                        >
                          <option value="">미지정</option>
                          {reporters.map(r => (
                            <option key={r.id} value={r.id}>{r.name}</option>
                          ))}
                        </select>
                      ) : (
                        <span className={`text-xs font-bold ${isMySection ? 'text-[#004b93]' : 'text-gray-400'}`}>
                          {sec.reporter_name || sec.reporter_nickname || '미지정'}
                          {isMySection && user.role === 'reporter' && ' (나)'}
                        </span>
                      )}

                      {/* 상태 뱃지 */}
                      {getStatusBadge(sec.article_status)}

                      {/* 컨펌 요청 표시 */}
                      {hasConfirmRequest && isAdmin && (
                        <span className="w-3 h-3 bg-red-500 rounded-full animate-pulse"></span>
                      )}

                      {isMySection && (
                        <i className="fas fa-chevron-right text-gray-300"></i>
                      )}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      ))}
    </main>
  );
}

export default NewspaperDetail;
